script:
frappe.ui.form.on('Room Booking', {
    room_type: function(frm) {
        frm.set_query('room_rate_plan', function() {
            return { filters: { room_type: frm.doc.room_type } };
        });
    }
});

function update_amount(cdt, cdn) {
    let row = locals[cdt][cdn];
    frappe.model.set_value(cdt, cdn, 'amount', (row.rate || 0) * (row.qty || 0));
}
function calculate_accommodation(frm) {
    if (!frm.doc.room_rate_plan || !frm.doc.calculation_type) {
        frm.accommodation_rate = 0;
        calculate_total(frm);
        return;
    }
    frappe.db.get_doc('Room Rate Plan', frm.doc.room_rate_plan).then(rate_plan => {
        frm.accommodation_rate = frm.doc.calculation_type === 'Hourly'
            ? (rate_plan.hourly_rate || 0)
            : (rate_plan.daily_rate || 0);
        calculate_total(frm);
    });
}

function calculate_total(frm) {
    let qty = 0;
    if (frm.doc.check_in && frm.doc.check_out && frm.doc.calculation_type) {
        let start = moment(frm.doc.check_in);
        let end = moment(frm.doc.check_out);
        if (frm.doc.calculation_type === 'Hourly') {
            qty = Math.ceil(end.diff(start, 'hours', true));
        } else {
            qty = Math.max(end.diff(start, 'days'), 1);
        }
    }
    let accommodation_total = (frm.accommodation_rate || 0) * qty;
    let services_total = (frm.doc.services || []).reduce((s, r) => s + (r.amount || 0), 0);
    let items_total = (frm.doc.items || []).reduce((s, r) => s + (r.amount || 0), 0);

    frm.set_value('total_amount', accommodation_total + services_total + items_total);
}

frappe.ui.form.on('Room Booking', {
    onload: function(frm) {
        frappe.db.get_single_value('Selling Settings', 'selling_price_list').then(pl => {
            frm.default_price_list = pl;
        });
    },
    room_rate_plan: function(frm) { calculate_accommodation(frm); },
    calculation_type: function(frm) { calculate_accommodation(frm); },
    check_in: function(frm) { calculate_total(frm); },
    check_out: function(frm) { calculate_total(frm); }
});

function update_rate(frm, cdt, cdn, table_field) {
    let row = locals[cdt][cdn];
    let item_code = row.item || row.service;
    if (!item_code || !row.price_list) return;

    frappe.call({
        method: 'frappe.client.get_list',
        args: {
            doctype: 'Item Price',
            filters: { item_code: item_code, price_list: row.price_list },
            fields: ['price_list_rate'],
            limit_page_length: 1
        },
        callback: function(r) {
            let rate = (r.message && r.message[0]) ? r.message[0].price_list_rate : 0;
            frappe.model.set_value(cdt, cdn, 'rate', rate);
            update_amount(cdt, cdn);
            frm.refresh_field(table_field);
            calculate_total(frm);
        }
    });
}

frappe.ui.form.on('Room Booking Item', {
    items_add: function(frm, cdt, cdn) {
        frappe.model.set_value(cdt, cdn, 'price_list', frm.default_price_list);
    },
    items_remove: function(frm) { calculate_total(frm); },
    item: function(frm, cdt, cdn) { update_rate(frm, cdt, cdn, 'items'); },
    price_list: function(frm, cdt, cdn) { update_rate(frm, cdt, cdn, 'items'); },
    qty: function(frm, cdt, cdn) { update_amount(cdt, cdn); calculate_total(frm); }
});

frappe.ui.form.on('Room Booking Service', {
    services_add: function(frm, cdt, cdn) {
        frappe.model.set_value(cdt, cdn, 'price_list', frm.default_price_list);
    },
    services_remove: function(frm) { calculate_total(frm); },
    service: function(frm, cdt, cdn) { update_rate(frm, cdt, cdn, 'services'); },
    price_list: function(frm, cdt, cdn) { update_rate(frm, cdt, cdn, 'services'); },
    qty: function(frm, cdt, cdn) { update_amount(cdt, cdn); calculate_total(frm); }
});
